// Cross-check of the engine against MATLAB (vectors in src/validation/ref_*.json,
// generated by matlab/fase*/val_*.m).
import { describe, expect, it } from 'vitest';
import { antennaChecks, couplingChecks, envChecks, failing as failed, passes, radarChecks, type Check } from '../src/validation/compare';

const show = (cs: Check[]) => {
  for (const c of cs) console.log(`${c.info ? 'INF' : passes(c) ? 'OK ' : 'MAL'} ${c.caso.padEnd(40)} ${c.metrica.padEnd(56)} ${c.valor.toFixed(4)} ${c.unidad} (tol ${c.tol})`);
};
const failing = (cs: Check[]) => failed(cs).map(c => `${c.caso}: ${c.metrica} = ${c.valor.toFixed(3)} ${c.unidad}`);

describe('validation against MATLAB', () => {
  it('antenna (Phased Array System Toolbox)', () => {
    const { checks } = antennaChecks(); show(checks);
    expect(failing(checks)).toEqual([]);
  });
  it('mutual coupling (Antenna Toolbox, MoM)', () => {
    const { checks } = couplingChecks(); show(checks);
    expect(failing(checks)).toEqual([]);
  });
  it('radar equation, detection and horizon (Radar Toolbox)', () => {
    const { checks } = radarChecks(); show(checks);
    expect(failing(checks)).toEqual([]);
  });
  it('environment: propagation, clutter, attenuation and refraction', () => {
    const { checks } = envChecks(); show(checks);
    expect(failing(checks)).toEqual([]);
  });
});
